/**
 * Order-options helpers for the Apple Pay quick-buy flow — keeps <salla-quick-buy> to thin AP wiring.
 * Apple Pay resolves options inside the session-started hook (single gesture), so the caller owns
 * the ApplePaySession and drives it via callbacks.
 */
export type OrderOptionEntry = {
    id: number | string;
    value: any;
};
/** Sync PDP-option validity (an `await` would consume the Apple Pay gesture). Skips hidden/disabled inputs. */
export declare function reportProductOptionsValiditySync(productId: string | number): boolean;
/** Merge collected order-options into the quick-purchase payload (FormData or plain object). */
export declare function appendOrderOptionsToPayload(data: any, orderOptions: OrderOptionEntry[]): void;
/**
 * Fetch order options and, if any, collect them via the modal (apple-pay mode). Callbacks drive the
 * caller's pre-created session: `beginPendingSession` (no options), `discardPendingSession` (options
 * found — the modal's AP button starts a fresh one), `onSubmit` (submitted).
 */
export declare function resolveApplePayOrderOptions(opts: {
    productId: string | number;
    amount: number;
    quantity: number;
    beginPendingSession: () => void;
    discardPendingSession: () => void;
    onSubmit: (selections: OrderOptionEntry[], total: number) => void;
}): Promise<void>;
